module benchmark/solution

import std/json (Json, JObject, JArray, decode, encode, jint, js)
import std/list (map)
import std/string (join)

pure func setField(j: Json, k: string, v: Json) -> Json =
  match j {
    JObject(fields) => JObject(map(\f. if f.key == k then {key: f.key, value: v} else f, fields)),
    other => other
  }

pure func render(j: Json) -> string =
  match j {
    JObject(fields) => "{${join(", ", map(\f. "${encode(js(f.key))}: ${render(f.value)}", fields))}}",
    JArray(items) => "[${join(", ", map(render, items))}]",
    other => encode(other)
  }

export func main() -> () ! {IO} {
  let src = "{\"name\": \"alice\", \"age\": 30, \"role\": \"engineer\"}";
  match decode(src) {
    Ok(obj) => {
      let updated = setField(setField(obj, "age", jint(31)), "role", js("senior engineer"));
      println(render(updated))
    },
    Err(e) => println(e)
  }
}

